CREATE OR REPLACE FUNCTION public.confirm_admin_payment(_payment_id uuid,_user_id uuid) RETURNS jsonb LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.payments%ROWTYPE; s public.subscriptions%ROWTYPE; sale public.sales%ROWTYPE; expires timestamptz; pct numeric; received numeric; BEGIN IF auth.uid() IS NULL OR auth.uid()<>_user_id OR NOT public.is_admin() THEN RAISE EXCEPTION 'Acesso negado.'; END IF; SELECT * INTO p FROM public.payments WHERE id=_payment_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pagamento não encontrado.'; END IF; IF p.status='paid' THEN RETURN jsonb_build_object('ok',true,'already',true,'sellerMissing',false); END IF; IF p.status<>'pending' OR p.amount<=0 THEN RAISE EXCEPTION 'Somente pagamentos pendentes com valor positivo podem ser confirmados.'; END IF; IF p.kind='plate' THEN SELECT * INTO sale FROM public.sales WHERE id=p.sale_id AND company_id=p.company_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Vincule a venda da mesma empresa.'; END IF; SELECT coalesce(sum(amount),0) INTO received FROM public.payments WHERE sale_id=sale.id AND status='paid'; IF received+p.amount>sale.amount THEN RAISE EXCEPTION 'O recebimento ultrapassa o valor da venda.'; END IF; UPDATE public.sales SET payment_status=CASE WHEN received+p.amount=sale.amount THEN 'paid'::public.payment_status ELSE 'pending'::public.payment_status END WHERE id=sale.id; ELSE SELECT * INTO s FROM public.subscriptions WHERE id=p.subscription_id AND company_id=p.company_id AND status<>'cancelled' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Vincule uma assinatura válida da mesma empresa.'; END IF; expires:=greatest(s.expires_at,now())+interval '1 year'; UPDATE public.subscriptions SET expires_at=expires,status='active' WHERE id=s.id; SELECT commission_renewal_percent INTO pct FROM public.settings WHERE id=true; IF s.seller_id IS NOT NULL AND coalesce(pct,0)>0 THEN INSERT INTO public.commissions(seller_id,kind,subscription_id,payment_id,base_amount,percent,amount,status) VALUES(s.seller_id,'renewal',s.id,p.id,p.amount,pct,round(p.amount*pct/100,2),'pending') ON CONFLICT(payment_id) WHERE payment_id IS NOT NULL AND kind='renewal' DO NOTHING; END IF; END IF; UPDATE public.payments SET status='paid',paid_at=now() WHERE id=p.id; INSERT INTO public.audit_logs(user_id,action,entity,entity_id,details) VALUES(_user_id,'payment.confirm','payments',p.id::text,jsonb_build_object('amount',p.amount,'kind',p.kind)); RETURN jsonb_build_object('ok',true,'already',false,'sellerMissing',p.kind<>'plate' AND s.seller_id IS NULL,'expiresAt',expires); END $$;
REVOKE ALL ON FUNCTION public.confirm_admin_payment(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.confirm_admin_payment(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.protect_confirmed_financial_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.status='paid' AND (TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD) THEN RAISE EXCEPTION 'Registro confirmado não pode ser alterado ou excluído.'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_paid_payments BEFORE UPDATE OR DELETE ON public.payments FOR EACH ROW EXECUTE FUNCTION public.protect_confirmed_financial_record();
CREATE TRIGGER protect_paid_commissions BEFORE UPDATE OR DELETE ON public.commissions FOR EACH ROW EXECUTE FUNCTION public.protect_confirmed_financial_record();
CREATE OR REPLACE FUNCTION public.activate_registered_plate(_code text,_company_name text,_review_url text,_contact jsonb,_accepted boolean,_annual_price numeric) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; configured numeric; company_uuid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Acesso negado.'; END IF; SELECT subscription_price INTO configured FROM public.settings WHERE id=true FOR SHARE; IF _accepted IS DISTINCT FROM true OR _annual_price IS DISTINCT FROM configured THEN RAISE EXCEPTION 'Confirme o aceite do valor anual atual.'; END IF; IF jsonb_typeof(_contact)<>'object' OR octet_length(_contact::text)>3000 OR coalesce(_contact->>'whatsapp','')='' OR coalesce(_contact->>'document','')='' OR coalesce(_contact->>'street','')='' OR coalesce(_contact->>'city','')='' THEN RAISE EXCEPTION 'Complete os dados de cadastro.'; END IF; result:=public.activate_plate(_code,_company_name,nullif(_review_url,'')); company_uuid:=(result->>'companyId')::uuid; UPDATE public.companies SET contact=_contact WHERE id=company_uuid AND owner_id=auth.uid(); UPDATE public.plates SET annual_consent_at=now(),annual_consent_version='2026-11-13',annual_consent_amount=configured WHERE qr_code=_code; INSERT INTO public.payments(company_id,sale_id,kind,amount,status) SELECT company_id,id,'plate',amount,'pending' FROM public.sales WHERE plate_id=(SELECT id FROM public.plates WHERE qr_code=_code) ORDER BY created_at DESC LIMIT 1; RETURN result; END $$;